#include <stdio.h>

/* teste do desafio soma-ate-sentinela — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo os numeros que a pessoa "digitaria",
   aponta o stdin para esse arquivo (freopen), captura o stdout no proprio
   teste e le a linha de volta. Os nomes dos arquivos temporarios sao POR
   CENARIO. Nunca ha fclose de stdin/stdout — so fflush — para o proximo
   freopen ficar legal (C11 7.21.4). As tres listas sao diferentes: uma soma
   escrita a mao reprova em pelo menos duas delas. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void somaAteSentinela(void);

SM_TEST(a_soma_de_cinco_sete_tres) {
    /* o que a pessoa digita nesta rodada */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "5 7 3 -1\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    somaAteSentinela();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a soma de 5, 7 e 3", linha, "15\n",
              "o -1 avisa o fim: entram na soma so os tres numeros antes dele");
    /* a saida TERMINA na primeira linha — buffer NOVO com sentinel */
    char fim[80] = "(nada impresso)";
